'use strict';

let base = {};
try { base = $('Set | Scheduler Constants | StateScheduler').first().json || {}; } catch {}
const clean = value => String(value ?? '').normalize('NFKC').trim();
const rows = $input.all().flatMap(item => {
  const value = item?.json?.body ?? item?.json ?? {};
  return Array.isArray(value) ? value : (Array.isArray(value?.data) ? value.data : [value]);
});

return rows.filter(row => row &&
  /^[0-9a-f-]{36}$/i.test(clean(row.candidate_id ?? row.candidateId)) &&
  /^[0-9a-f-]{36}$/i.test(clean(row.lease_token ?? row.leaseToken)) &&
  Number.isSafeInteger(Number(row.candidate_version ?? row.candidateVersion)) &&
  clean(row.delivery_address ?? row.deliveryAddress) &&
  /^[0-9a-f]{32}$/i.test(clean(row.callback_token ?? row.callbackToken))
).map(row => {
  const candidateId = clean(row.candidate_id ?? row.candidateId).toLowerCase();
  const candidateVersion = Number(row.candidate_version ?? row.candidateVersion);
  const leaseToken = clean(row.lease_token ?? row.leaseToken).toLowerCase();
  const attemptNo = Number(row.attempt_no ?? row.attemptNo ?? 1);
  const beginRpcBody = {
    p_candidate_id: candidateId,
    p_lease_token: leaseToken,
    p_expected_version: candidateVersion,
    p_send_key: `proactivity:${candidateId}:a${attemptNo}:v${candidateVersion}`
  };
  return { json: {
    ...base,
    ...row,
    stateProactivityReady: true,
    stateProactivityClaim: row,
    stateProactivityBeginRpcBody: beginRpcBody,
    stateRpcBody: beginRpcBody
  } };
});

'use strict';

const source = $('Code | Normalize Proactivity Claims | Proactivity').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const clean = value => String(value ?? '').normalize('NFKC').trim();
const claim = source.stateProactivityClaim || {};
const candidateId = clean(claim.candidate_id ?? claim.candidateId).toLowerCase();
const callbackToken = clean(claim.callback_token ?? claim.callbackToken).toLowerCase();
const category = clean(claim.category);
const payload = claim.payload_json && typeof claim.payload_json === 'object' ? claim.payload_json : {};
const valid = Boolean(body && typeof body === 'object' && !Array.isArray(body) &&
  body.contractVersion === 'chelsea_proactivity_send_begin_v1' && body.telegramSendAllowed === true &&
  clean(body.candidateId).toLowerCase() === candidateId &&
  clean(body.sendKey) === clean(source.stateProactivityBeginRpcBody?.p_send_key) &&
  Number.isSafeInteger(Number(body.candidateVersion)) && /^[0-9a-f]{32}$/.test(callbackToken));

const callback = action => `cpa:v1:${action}:${callbackToken}`;
let text = '';
let buttons = [];
if (category === 'morning') {
  text = 'Утреннее взаимодействие: узнай главный желаемый результат пользователя на сегодня.';
  buttons = [
    [{ text: '✍️ Ответить', additionalFields: { callback_data: callback('r') } }],
    [{ text: '⏰ Позже', additionalFields: { callback_data: callback('l') } }, { text: '⏭️ Пропустить сегодня', additionalFields: { callback_data: callback('s') } }]
  ];
} else if (category === 'evening') {
  text = 'Вечернее взаимодействие: попроси рассказать о прошедшем дне, событиях, результатах и состоянии.';
  buttons = [
    [{ text: '✍️ Ответить', additionalFields: { callback_data: callback('r') } }],
    [{ text: '⏰ Позже', additionalFields: { callback_data: callback('l') } }, { text: '⏭️ Пропустить сегодня', additionalFields: { callback_data: callback('s') } }]
  ];
} else if (category === 'unfinished_clarification') {
  text = clean(payload.questionText);
  buttons = [
    [{ text: '✍️ Ответить', additionalFields: { callback_data: callback('r') } }],
    [{ text: '⏭️ Пропустить уточнения', additionalFields: { callback_data: callback('s') } }],
    [{ text: '⏰ Позже', additionalFields: { callback_data: callback('l') } }, { text: '✖️ Закрыть вопрос', additionalFields: { callback_data: callback('c') } }]
  ];
} else if (category === 'profile_question') {
  text = clean(payload.questionText);
  buttons = [
    [{ text: '✍️ Ответить', additionalFields: { callback_data: callback('r') } }],
    [{ text: '⏰ Позже', additionalFields: { callback_data: callback('l') } }, { text: '✖️ Закрыть вопрос', additionalFields: { callback_data: callback('c') } }]
  ];
} else if (category === 'check_in') {
  text = clean(payload.questionText) || 'Узнай, чем пользователь сейчас занят и как себя чувствует.';
  buttons = [
    [{ text: '✍️ Ответить', additionalFields: { callback_data: callback('r') } }],
    [{ text: '⏰ Позже', additionalFields: { callback_data: callback('l') } }, { text: '✖️ Закрыть вопрос', additionalFields: { callback_data: callback('c') } }]
  ];
}
const keyboard = { rows: buttons.map(row => ({ row: { buttons: row } })) };

return [{ json: {
  ...source,
  stateProactivityBeginResult: body,
  stateProactivityBeginValid: valid && Boolean(text && buttons.length),
  stateProactivityTelegramSendAllowed: valid && Boolean(text && buttons.length),
  stateProactivitySendingVersion: valid ? Number(body.candidateVersion) : Number(source.stateProactivityBeginRpcBody?.p_expected_version),
  stateProactivityChatId: clean(claim.delivery_address ?? claim.deliveryAddress),
  stateProactivityPromptText: text,
  stateProactivityMessageIntent: {
    category,
    semanticInstruction: text,
    targetLocalDate: clean(claim.target_local_date ?? claim.targetLocalDate),
    mode: clean(claim.mode_code ?? claim.modeCode),
    payload
  },
  stateProactivityInlineKeyboard: keyboard,
  stateProactivitySendError: valid ? '' : clean(body?.message || body?.error?.message || body?.hint || 'proactivity_send_begin_invalid').slice(0, 2000)
} }];

'use strict';

const source = $('Code | Validate Proactivity Send Begin | Proactivity').item.json || {};
const incoming = $input.first()?.json || {};
const response = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const message = response?.result && typeof response.result === 'object' ? response.result : response;
const clean = value => String(value ?? '').normalize('NFKC').trim();
const messageId = clean(message?.message_id);
const responseChatId = clean(message?.chat?.id);
const expectedChatId = clean(source.stateProactivityChatId);
const explicitFailure = Boolean(response?.ok === false || incoming?.ok === false || response?.error || incoming?.error);
const exactReceipt = Boolean(source.stateProactivityBeginValid === true && !explicitFailure &&
  /^\d+$/.test(messageId) && /^-?\d+$/.test(responseChatId) && responseChatId === expectedChatId);

const base = source.stateProactivityBeginRpcBody || {};
return [{ json: {
  ...source,
  stateProactivityTelegramReceipt: response,
  stateProactivityTelegramReceiptExact: exactReceipt,
  stateProactivityCompleteRpcBody: exactReceipt ? {
    p_candidate_id: clean(base.p_candidate_id),
    p_lease_token: clean(base.p_lease_token),
    p_expected_version: Number(source.stateProactivitySendingVersion),
    p_send_key: clean(base.p_send_key),
    p_chat_id: responseChatId,
    p_message_id: messageId,
    p_receipt: response
  } : null,
  stateProactivityUncertainRpcBody: exactReceipt ? null : {
    p_candidate_id: clean(base.p_candidate_id),
    p_lease_token: clean(base.p_lease_token),
    p_expected_version: Number(source.stateProactivitySendingVersion),
    p_error_code: explicitFailure ? 'proactivity_telegram_rejected' : 'proactivity_telegram_receipt_invalid'
  },
  stateRpcBody: exactReceipt ? {
    p_candidate_id: clean(base.p_candidate_id), p_lease_token: clean(base.p_lease_token),
    p_expected_version: Number(source.stateProactivitySendingVersion), p_send_key: clean(base.p_send_key),
    p_chat_id: responseChatId, p_message_id: messageId, p_receipt: response
  } : null
} }];

'use strict';

const source = $input.first()?.json || {};
const ready = source.stateProactivityBeginValid === true && source.stateProactivityTelegramReceiptExact !== true &&
  source.stateProactivityUncertainRpcBody && typeof source.stateProactivityUncertainRpcBody === 'object';
return [{ json: {
  ...source,
  stateProactivityUncertainReady: ready,
  stateRpcBody: ready ? source.stateProactivityUncertainRpcBody : null
} }];

'use strict';

const ContextualClarification = (() => {
  const clean = value => String(value ?? '').normalize('NFKC').replace(/\s+/g, ' ').trim();
  const normalized = value => clean(value).toLocaleLowerCase('ru-RU').replace(/ё/g, 'е');
  const ymdPattern = /^\d{4}-\d{2}-\d{2}$/;
  const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  const formalPattern = /(?:^|[^\p{L}])(?:вы|вас|вам|вами|ваш|ваша|ваше|ваши|вашего|вашей|вашим|вашими|ваших)(?=$|[^\p{L}])/iu;
  const vagueReferences = new Set([
    'это','эта нагрузка','нагрузка','все','всё','ситуация','эта ситуация','это событие','произошедшее'
  ].map(normalized));
  const tokenStop = new Set([
    'это','эта','этот','эти','была','было','были','сегодня','вчера','июля','августа','сентября',
    'октября','ноября','декабря','января','февраля','марта','апреля','мая','июня','событие'
  ]);

  function localDate(timezone, localTimestamp = '') {
    const supplied = clean(localTimestamp).slice(0, 10);
    if (ymdPattern.test(supplied)) return supplied;
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: clean(timezone) || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit'
    }).formatToParts(new Date());
    const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
    return `${values.year}-${values.month}-${values.day}`;
  }

  function utcDay(value) {
    if (!ymdPattern.test(value)) return Number.NaN;
    const [year,month,day] = value.split('-').map(Number);
    const time = Date.UTC(year,month - 1,day);
    const check = new Date(time);
    return check.getUTCFullYear() === year && check.getUTCMonth() === month - 1 && check.getUTCDate() === day
      ? Math.floor(time / 86400000)
      : Number.NaN;
  }

  function dateReference(sourceLocalDate, currentLocalDate) {
    const sourceDay = utcDay(sourceLocalDate);
    const currentDay = utcDay(currentLocalDate);
    if (!Number.isFinite(sourceDay) || !Number.isFinite(currentDay)) return { ready: false, error: 'local_date_invalid' };
    const delta = currentDay - sourceDay;
    if (delta < 0) return { ready: false, error: 'future_event_for_state_clarification', deltaDays: delta };
    if (delta === 0) return { ready: true, value: 'сегодня', deltaDays: 0 };
    if (delta === 1) return { ready: true, value: 'вчера', deltaDays: 1 };
    const [sourceYear,sourceMonth,sourceDate] = sourceLocalDate.split('-').map(Number);
    const currentYear = Number(currentLocalDate.slice(0,4));
    return {
      ready: true,
      value: `${sourceDate} ${months[sourceMonth - 1]}${sourceYear === currentYear ? '' : ` ${sourceYear} года`}`,
      deltaDays: delta
    };
  }

  function derive(contextValue, timezone, localTimestamp = '') {
    const context = contextValue && typeof contextValue === 'object' && !Array.isArray(contextValue)
      ? contextValue : {};
    const unresolvedSlots = Array.isArray(context.unresolvedSlots)
      ? context.unresolvedSlots.map(slot => ({
          code: clean(slot?.code), label: clean(slot?.label), questionHint: clean(slot?.questionHint)
        })).filter(slot => slot.code && slot.label && slot.questionHint)
      : [];
    const currentLocalDate = localDate(timezone, localTimestamp);
    const sourceLocalDate = clean(context.sourceLocalDate);
    const reference = dateReference(sourceLocalDate, currentLocalDate);
    const eventLabel = clean(context.eventLabel);
    const eventSummary = clean(context.eventSummary);
    const evidenceText = clean(context.evidenceText);
    const resolvedSlots = context.resolvedSlots && typeof context.resolvedSlots === 'object' && !Array.isArray(context.resolvedSlots)
      ? context.resolvedSlots : {};
    const baseReady = context.contractVersion === 'chelsea_clarification_context_v1' &&
      /^[a-z][a-z0-9_]{1,63}$/.test(clean(context.eventRuleCode)) &&
      Boolean(eventLabel && (eventSummary || evidenceText) && unresolvedSlots.length && reference.ready);
    return {
      ready: baseReady,
      error: baseReady ? '' : (reference.error || 'clarification_context_invalid'),
      contractVersion: clean(context.contractVersion),
      sourceLocalDate,
      currentLocalDate,
      dateReference: reference.value || '',
      deltaDays: reference.deltaDays,
      eventRuleCode: clean(context.eventRuleCode),
      eventLabel,
      eventSummary,
      evidenceText,
      anchorQuality: clean(context.anchorQuality),
      resolvedSlots,
      unresolvedSlots,
      unresolvedSlotCodes: unresolvedSlots.map(slot => slot.code)
    };
  }

  function tokens(value) {
    return normalized(value).match(/[\p{L}\p{N}]+/gu)?.filter(token => token.length >= 3 && !tokenStop.has(token)) || [];
  }

  function exactCodes(actual, expected) {
    if (!Array.isArray(actual) || actual.some(code => !clean(code))) return false;
    const left = actual.map(clean);
    const right = expected.map(clean);
    return left.length === new Set(left).size && left.length === right.length &&
      [...left].sort().join('\u0000') === [...right].sort().join('\u0000');
  }

  function validateResponse(parsed, contract, preferredName, maxLength = 350) {
    const text = clean(parsed?.text);
    const dateRef = clean(parsed?.dateReference);
    const eventRef = clean(parsed?.eventReference);
    const asked = Array.isArray(parsed?.askedSlotCodes) ? parsed.askedSlotCodes.map(clean) : [];
    const normalizedText = normalized(text);
    const normalizedName = normalized(preferredName);
    let nameCount = 0;
    let cursor = 0;
    while (normalizedName && (cursor = normalizedText.indexOf(normalizedName,cursor)) >= 0) {
      nameCount += 1;
      cursor += normalizedName.length;
    }
    const dateValid = dateRef === contract.dateReference && normalizedText.includes(normalized(dateRef));
    const eventVisible = Boolean(eventRef && normalizedText.includes(normalized(eventRef)));
    const grounding = normalized(`${contract.eventLabel} ${contract.eventSummary} ${contract.evidenceText}`);
    const eventTokens = tokens(eventRef);
    const eventGrounded = eventVisible && !vagueReferences.has(normalized(eventRef)) &&
      eventTokens.length > 0 && eventTokens.some(token => grounding.includes(token));
    const slotsValid = exactCodes(asked,contract.unresolvedSlotCodes);
    const checks = {
      text: Boolean(text && text.length <= maxLength),
      name: nameCount === 1,
      informal: !formalPattern.test(text),
      date: dateValid,
      event: eventGrounded,
      slots: slotsValid
    };
    const firstError = Object.entries(checks).find(([,passed]) => !passed)?.[0] || '';
    return {
      ready: Object.values(checks).every(Boolean),
      error: firstError ? `contextual_clarification_${firstError}_invalid` : '',
      text,dateReference:dateRef,eventReference:eventRef,askedSlotCodes:asked,checks
    };
  }

  return { clean, normalized, derive, validateResponse };
})();


const input = $input.first()?.json || {};
const claim = input.stateProactivityClaim || {};
const clean = ContextualClarification.clean;
const composition = claim.composition_context && typeof claim.composition_context === 'object'
  ? claim.composition_context
  : (claim.compositionContext && typeof claim.compositionContext === 'object' ? claim.compositionContext : {});
const preferredName = clean(
  claim.preferred_name ?? claim.preferredName ?? composition.preferredName ??
  composition.displayName ?? claim.current_username ?? claim.currentUsername
).replace(/[,;:]+$/u,'').trim();
const intent = input.stateProactivityMessageIntent || {};
const category = clean(intent.category || claim.category);
const semanticInstruction = clean(intent.semanticInstruction || input.stateProactivityPromptText);
const payload = intent.payload && typeof intent.payload === 'object' ? intent.payload : {};
const contextual = category === 'unfinished_clarification';
const timezone = clean(claim.timezone || composition.timezone) || 'UTC';
const contract = contextual
  ? ContextualClarification.derive(payload.clarificationContext,timezone,clean(composition.localTimestamp))
  : { ready: true,dateReference: '',unresolvedSlotCodes: [] };
const ready = input.stateProactivityTelegramSendAllowed === true &&
  Boolean(preferredName && category && semanticInstruction && contract.ready);

const commonRules = [
  'Ты — Челси и пишешь короткое живое сообщение одному человеку в Telegram.',
  `Его имя: ${preferredName}. Назови его ровно один раз и общайся только на «ты».`,
  'Не используй «Вы», «вас», «вам», «ваш» и другие формальные формы.',
  'Не используй шаблонные служебные фразы, не объясняй правила и не упоминай модель.',
  'Не выдумывай факты. Верни только JSON по схеме.'
];
const contextualRules = [
  'Это напоминание о незавершённом уточнении. Используй только clarificationContext; recentEvents для привязки запрещены.',
  'В первом коротком предложении обязательно явно назови dateReference и конкретное исходное событие.',
  'eventReference должен быть коротким буквальным фрагментом eventSummary или evidenceText и обязан присутствовать в text.',
  'Спроси только про unresolvedSlots; resolvedSlots повторно не спрашивай.',
  'Запрещены самостоятельные расплывчатые ссылки «эта нагрузка», «это», «всё», «ситуация». Сначала назови событие.',
  'askedSlotCodes верни ровно для всех и только unresolvedSlots. dateReference верни без изменения.',
  'Текст — 1–2 коротких предложения, не более 350 символов.'
];
const ordinaryRules = [
  'Сформулируй 1–3 коротких предложения, сохрани заданный смысл.',
  'Поля dateReference и eventReference верни пустыми строками, askedSlotCodes — пустым массивом.'
];
const userPayload = contextual ? {
  category,semanticInstruction,preferredName,timezone,
  dateReference: contract.dateReference,
  sourceLocalDate: contract.sourceLocalDate,
  eventRuleCode: contract.eventRuleCode,
  eventLabel: contract.eventLabel,
  eventSummary: contract.eventSummary,
  evidenceText: contract.evidenceText,
  anchorQuality: contract.anchorQuality,
  resolvedSlots: contract.resolvedSlots,
  unresolvedSlots: contract.unresolvedSlots,
  recentEvents: []
} : {
  category,semanticInstruction,preferredName,
  targetLocalDate: clean(intent.targetLocalDate || claim.target_local_date || claim.targetLocalDate),
  timezone,localTimestamp: clean(composition.localTimestamp),
  mode: clean(intent.mode || claim.mode_code || claim.modeCode),payload,
  currentState: Array.isArray(composition.currentState) ? composition.currentState.slice(0,10) : [],
  recentEvents: Array.isArray(composition.recentEvents) ? composition.recentEvents.slice(0,5) : []
};
const request = {
  model: 'gpt-4.1-mini',
  input: [
    { role: 'system',content: [{ type: 'input_text',text: [...commonRules,...(contextual ? contextualRules : ordinaryRules)].join('\n') }] },
    { role: 'user',content: [{ type: 'input_text',text: JSON.stringify(userPayload) }] }
  ],
  temperature: contextual ? 0.65 : 0.85,
  max_output_tokens: 240,
  text: { format: { type: 'json_schema',name: 'chelsea_micro_message_v2',strict: true,schema: {
    type: 'object',additionalProperties: false,
    required: ['text','dateReference','eventReference','askedSlotCodes'],
    properties: {
      text: { type: 'string',minLength: 8,maxLength: 500 },
      dateReference: { type: 'string',maxLength: 40 },
      eventReference: { type: 'string',maxLength: 160 },
      askedSlotCodes: { type: 'array',items: { type: 'string' },maxItems: 12 }
    }
  } } }
};

return [{ json: {
  ...input,
  chelseaMicroPreferredName: preferredName,
  chelseaMicroRequestReady: ready,
  chelseaMicroRequestError: ready ? '' : (contract.error || 'proactivity_request_invalid'),
  chelseaMicroRequest: ready ? request : {},
  chelseaMicroContextualClarification: contextual,
  chelseaMicroClarificationContract: contract,
  chelseaMicroPromptVersion: contextual ? 'chelsea_micro_proactivity_contextual_v2' : 'chelsea_micro_proactivity_v2',
  chelseaMicroModel: 'gpt-4.1-mini'
} }];

